/* Assistance Services Database Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Alexa": "Amazon's voice assistant, named for the Library of Alexandria.", "Siri": "beautiful victory — Norwegian", "Cortana": "Microsoft's assistant, named for the AI of the Halo games, whose name echoes the sword Curtana.", "Bixby": "Samsung's voice assistant brand name.", "Mycroft": "The open-source voice assistant, named for Sherlock's brother Mycroft Holmes.", "Watson": "IBM's question-answering system, named for the company's founder.", "Google Assistant": "The brand-product compound: Google's assistant line.", "Amazon Alexa": "The brand-product compound: Amazon's assistant line.", "Apple Siri": "The brand-product compound: Apple's assistant line.", "Microsoft Copilot": "Microsoft's assistant line under the Copilot name."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Alexa';
console.log(lookup(q));

